      if (h >= ob.top - 0.05 || ob.bot >= h + PLAYER_H) continue;
      const rx = ob.hx + PLAYER_R, rz = ob.hz + PLAYER_R;
      const dx = x - ob.cx, dz = z - ob.cz;
      if (ob.round) {
        const ex = dx / rx, ez = dz / rz;
